const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Sichuan Basin region (approximate bounding box)
  var sichuanBasin = ee.Geometry.Polygon([
    [[103.0, 30.5], [108.5, 30.5], [108.5, 33.0], [103.0, 33.0], [103.0, 30.5]]
  ]);

  // Get MODIS aerosol data for 2006 and 2020
  var modis2006 = ee.ImageCollection('MODIS/061/MOD04_L2')
    .filterDate('2006-01-01', '2006-12-31')
    .filterBounds(sichuanBasin);

  var modis2020 = ee.ImageCollection('MODIS/061/MYD04_L2')
    .filterDate('2020-01-01', '2020-12-31')
    .filterBounds(sichuanBasin);

  // Check if collections are empty
  var count2006 = modis2006.size().getInfo();
  var count2020 = modis2020.size().getInfo();

  print(`2006 Images: ${count2006}`);
  print(`2020 Images: ${count2020}`);

  if (count2006 === 0 || count2020 === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Function to extract AOD and filter by quality
  function processAOD(img) {
    var aod = img.select('Optical_Depth_Land_And_Ocean');
    var qa = img.select('Quality_Assurance_Land');
    // Filter for good quality (QA bits 0-1 = 0 or 1)
    var qualityMask = qa.bitwiseAnd(3).lte(1);
    return aod.updateMask(qualityMask).multiply(0.001); // Scale factor
  }

  var processed2006 = modis2006.map(processAOD).mean();
  var processed2020 = modis2020.map(processAOD).mean();

  // Count valid pixels
  var countStats2006 = processed2006.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sichuanBasin,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  var countStats2020 = processed2020.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sichuanBasin,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  var valid2006 = countStats2006['Optical_Depth_Land_And_Ocean'];
  var valid2020 = countStats2020['Optical_Depth_Land_And_Ocean'];

  print(`2006 Valid Pixels: ${valid2006}`);
  print(`2020 Valid Pixels: ${valid2020}`);

  if (valid2006 === 0 || valid2020 === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // Calculate mean AOD values
  var aod2006 = processed2006.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: sichuanBasin,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  var aod2020 = processed2020.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: sichuanBasin,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  var mean2006 = aod2006['Optical_Depth_Land_And_Ocean'];
  var mean2020 = aod2020['Optical_Depth_Land_And_Ocean'];

  print(`2006 Mean AOD: ${mean2006.toFixed(3)}`);
  print(`2020 Mean AOD: ${mean2020.toFixed(3)}`);

  // Validate results
  if (mean2006 === null || mean2020 === null || 
      isNaN(mean2006) || isNaN(mean2020) ||
      mean2006 < 0 || mean2006 > 3 || 
      mean2020 < 0 || mean2020 > 3) {
    print("<answer>C3</answer>");
    return;
  }

  // Check if AOD decreased
  if (mean2020 < mean2006) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
